// ================================
// อ่าน webhook ของ LINE + ดูว่าอยู่ในช่วงเวลาเช็คชื่อไหม
// ⚠️ EXCLUDED_USERS เป็น userId "ฝั่งบอทเดิม" — ถ้ายังต้องยกเว้นคนเดิม
//    ต้องเพิ่ม userId ฝั่งบอทใหม่ของคนนั้นด้วย (id ออกต่อ provider ของบอท)
// ================================
const EXCLUDED_USERS = [
  'Uef6d2bc60d52eb27b2ca4537f12dab8d',
  'U7cb0290647f850dcc4be7203e754f66e',
  'U1cb2b916b062d2ef42c6800d21165083',
  'U888dafebfcbaa734344faef930e57799'
];

const body = $json.body || $json;
const evt = body.events?.[0] || {};
const message = evt.message || {};
const timestamp = evt.timestamp ? new Date(evt.timestamp).toISOString() : new Date().toISOString();
const userId = evt.source?.userId || null;
if (EXCLUDED_USERS.includes(userId)) return [];

const thaiTime = new Date(new Date(timestamp).toLocaleString('en-US', { timeZone: 'Asia/Bangkok' }));
const thaiHours = thaiTime.getHours();
const thaiMinutes = thaiTime.getMinutes();
const currentTimeInMinutes = thaiHours * 60 + thaiMinutes;

const startTime = 6 * 60;
const endTime = 10 * 60;
const isWithinWorkingHours = currentTimeInMinutes >= startTime && currentTimeInMinutes <= endTime;

const y = thaiTime.getFullYear();
const m = String(thaiTime.getMonth() + 1).padStart(2, '0');
const d = String(thaiTime.getDate()).padStart(2, '0');
const todayDateKey = `${y}-${m}-${d}`;

const isImage = message.type === 'image';
const isText = message.type === 'text';
const textContent = isText ? (message.text || '') : null;

return [{ json: {
  raw: body,
  userId,
  groupId: evt.source?.groupId || null,
  replyToken: evt.replyToken || null,
  messageId: message.id || null,
  messageType: message.type || null,
  isImage, isText, textContent,
  timestamp,
  isWithinWorkingHours,
  currentTime: `${String(thaiHours).padStart(2,'0')}:${String(thaiMinutes).padStart(2,'0')}`,
  todayDateKey
}}];

// เช็คว่าวันนี้คนนี้เช็คชื่อไปแล้วหรือยัง (อ่านจากชีต "เช็คชื่อ" เหมือนเดิม)
const items = $input.all();
const w = $('Parse Webhook').item.json;
let found = false;
for (const it of items) {
  if (it.json.userId === w.userId && it.json.date_iso === w.todayDateKey) { found = true; break; }
}
return [{ json: {
  userId: w.userId,
  groupId: w.groupId,
  replyToken: w.replyToken,
  messageId: w.messageId,
  timestamp: w.timestamp,
  todayDateKey: w.todayDateKey,
  alreadyCheckedInToday: found,
  shouldContinue: !found
}}];

