parameters.text:
คุณคือระบบ OCR สำหรับ "รูปเช็คอินงาน" อ่านตัวหนังสือที่แปะบนรูป แล้วตอบเป็น JSON object เท่านั้น ห้ามมี markdown ถ้าไม่พบข้อมูลใส่ null

⚠️ การอ่านเวลา: "X นาฬิกา Y นาที Z วินาที" = HH:MM:SS (เติม 0 หน้าเลขหลักเดียว)

{
  "found_overlay_text": true/false,
  "overlay_text_raw": "ข้อความบนรูป",
  "datetime_in_image": {"thai_raw": null, "date_th": null, "time_hms": null, "time_hm": null, "year_be": null, "year_ad": null},
  "location_in_image": {"house_no": null, "road_or_route": null, "subdistrict": null, "district": null, "province": null, "postal_code": null, "country": null, "full_address": null},
  "quality": {"datetime_confidence": 0, "location_confidence": 0, "notes": ""}
}

parameters.jsCode:
// ================================
// สร้างแถวเช็คชื่อ — ★ ใช้ "เวลาเข้างานรายคน" จากฐานข้อมูล (เดิมฟิกซ์ 09:00 ทุกคน)
// ================================
function extractJsonFromGeminiText(text) {
  if (!text) return null;
  const s = String(text).trim();
  const fenced = s.match(/```json\s*([\s\S]*?)\s*```/i);
  const payload = fenced ? fenced[1].trim() : s;
  try { return JSON.parse(payload); } catch (e) {
    const obj = payload.match(/\{[\s\S]*\}/);
    if (!obj) return null;
    try { return JSON.parse(obj[0]); } catch (e2) { return null; }
  }
}
function beToAd(y) { const n = Number(y); return Number.isFinite(n) ? (n < 2400 ? n : n - 543) : null; }
function parseThaiDateToISO(dateTh, yearBE) {
  if (!dateTh) return null;
  const months = {'ม.ค.':1,'ก.พ.':2,'มี.ค.':3,'เม.ย.':4,'พ.ค.':5,'มิ.ย.':6,'ก.ค.':7,'ส.ค.':8,'ก.ย.':9,'ต.ค.':10,'พ.ย.':11,'ธ.ค.':12};
  const m = String(dateTh).trim().match(/(\d{1,2})\s+([^\s]+)\s+(\d{4})?/);
  if (!m) return null;
  const dd = Number(m[1]), mm = months[m[2]] || null;
  const yyRaw = m[3] ? Number(m[3]) : Number(yearBE);
  if (!dd || !mm || !yyRaw) return null;
  const yyAD = yyRaw >= 2400 ? yyRaw - 543 : yyRaw;
  if (yyAD < 2000 || yyAD > 2100) return null;
  return `${yyAD}-${String(mm).padStart(2,'0')}-${String(dd).padStart(2,'0')}`;
}

const items = $input.all().map(i => i.json);
const profileItem = items.find(x => x.displayName) || {};
const gemItem = items.find(x => x?.content?.parts?.[0]?.text) || $('Analyze Check-in Image').first().json;
const webhookData = $('Check If Already Checked In Today').first().json;

// ★ ข้อมูลพนักงานจากฐานข้อมูลเรา (ชื่อเล่น + เวลาเข้างานรายคน)
let emp = {};
try { emp = $('พนักงาน: userId นี้คือใคร').first().json || {}; } catch (e) { emp = {}; }
const empNick = emp['ชื่อเล่น'] || '';
const workStartRaw = (emp['เวลาเข้างาน'] || '').trim();   // "8:00" / "8:30" / "9:00"

let gemText = '';
if (gemItem?.content?.parts?.length) gemText = gemItem.content.parts.map(p => p.text || '').join('\n');
const extracted = extractJsonFromGeminiText(gemText) || {};
const dt = extracted.datetime_in_image || {};
const loc = extracted.location_in_image || {};
const q = extracted.quality || {};
const foundOverlay = extracted.found_overlay_text === true;

let fallbackDate = null, fallbackTime = null, fallbackTimeHMS = null, fallbackYearBE = null, fallbackYearAD = null;
if (webhookData.timestamp) {
  const d0 = new Date(webhookData.timestamp);
  if (!isNaN(d0.getTime())) {
    const t = new Date(d0.toLocaleString('en-US', { timeZone: 'Asia/Bangkok' }));
    fallbackYearAD = t.getFullYear();
    fallbackYearBE = fallbackYearAD + 543;
    fallbackDate = `${fallbackYearAD}-${String(t.getMonth()+1).padStart(2,'0')}-${String(t.getDate()).padStart(2,'0')}`;
    const hh = String(t.getHours()).padStart(2,'0'), mm = String(t.getMinutes()).padStart(2,'0'), ss = String(t.getSeconds()).padStart(2,'0');
    fallbackTimeHMS = `${hh}:${mm}:${ss}`;
    fallbackTime = `${hh}:${mm}`;
  }
}

const timeHM = dt.time_hm || (dt.time_hms ? String(dt.time_hms).slice(0,5) : null) || fallbackTime;
const timeHMS = dt.time_hms || fallbackTimeHMS;
const yearBE = dt.year_be ?? fallbackYearBE;
const yearAD = dt.year_ad ? beToAd(dt.year_ad) : (yearBE ? beToAd(yearBE) : fallbackYearAD);
const safeYearAD = (yearAD && yearAD >= 2000 && yearAD <= 2100) ? yearAD : fallbackYearAD;
const dateISO = parseThaiDateToISO(dt.date_th || null, yearBE) || (safeYearAD ? fallbackDate : null);
const checkinISO = (dateISO && timeHMS) ? `${dateISO}T${timeHMS}+07:00` : null;
const fullAddress = loc.full_address || [loc.house_no, loc.road_or_route, loc.district ? `อ.${loc.district}` : null,
  loc.province ? `จ.${loc.province}` : null, loc.postal_code, loc.country].filter(Boolean).join(' ').trim() || null;

// ── ตัดสินสาย/ตรงเวลา เทียบ "เวลาเข้างานของคนนั้น" ──
const ws = workStartRaw.match(/^(\d{1,2})[:.](\d{2})$/);
const limitMin = ws ? Number(ws[1]) * 60 + Number(ws[2]) : 9 * 60;   // ไม่มีข้อมูล = 09:00 แบบเดิม
let status = 'abnormal', reason = '';
if (!timeHM) {
  reason = foundOverlay ? 'อ่านเวลาจากรูปไม่ออก' : 'ไม่พบข้อความบนรูป และดึงเวลาจาก webhook ไม่ได้';
} else {
  const [hh, mm] = timeHM.split(':').map(Number);
  if (Number.isFinite(hh) && Number.isFinite(mm)) {
    const late = (hh * 60 + mm) > limitMin;
    const src = (foundOverlay && dt.time_hm) ? 'จากรูป' : 'จากเวลาส่ง';
    const limitTxt = ws ? workStartRaw : '9:00 (ไม่มีเวลาเข้างานในทะเบียน)';
    status = late ? 'late' : 'ontime';
    reason = `${late ? 'สาย' : 'ตรงเวลา'} (${src} · เข้างาน ${limitTxt})`;
  } else {
    reason = 'เวลาอ่านไม่ออก';
  }
}

return [{ json: {
  createdAt: new Date().toISOString(),
  userId: webhookData.userId || '',
  displayName: empNick || profileItem.displayName || '',   // ★ ใช้ชื่อเล่นจากทะเบียนก่อน
  pictureUrl: profileItem.pictureUrl || '',
  language: profileItem.language || '',
  found_overlay_text: foundOverlay,
  overlay_text_raw: extracted.overlay_text_raw || '',
  thai_raw: dt.thai_raw || '',
  date_th: dt.date_th || '',
  date_iso: fallbackDate || dateISO || '',
  time_hm: timeHM || '',
  time_hms: timeHMS || '',
  year_be: yearBE ?? '',
  year_ad: safeYearAD ?? '',
  checkin_iso: checkinISO || '',
  house_no: loc.house_no || '', road_or_route: loc.road_or_route || '', subdistrict: loc.subdistrict || '',
  district: loc.district || '', province: loc.province || '', postal_code: loc.postal_code || '',
  country: loc.country || '', full_address: fullAddress || '',
  datetime_confidence: q.datetime_confidence ?? '', location_confidence: q.location_confidence ?? '',
  notes: q.notes || '', status, reason
}}];

parameters.query:
SELECT "ชื่อเล่น", "ตำแหน่งงาน", "เวลาเข้างาน", "วันหยุด", line_user_ids
FROM v_employees
WHERE active;

parameters.jsCode:
// จับคู่ "ใครลา/สาย" จากข้อความในกลุ่ม — รายชื่อมาจากฐานข้อมูลเรา (ไม่ใช่ชีตแล้ว)
const w = $('Parse Webhook').first().json;
const rawText = (w.textContent || '').trim();
const senderUserId = w.userId;

const reportKeywords = ['ลา','หยุด','สาย','เลท','เข้าสาย','ทดเวลา','สลับ','ชดเชย','เปลี่ยนวันหยุด',
  'ติดธุระ','รถเสีย','ป่วย','ท้องเสีย','ไม่สบาย','หยุดยาว','หยุดเทศกาล','หยุดบริษัท','ลาพักร้อน',
  'หยุดนักขัตฤกษ์','วันหยุดราชการ'];
if (!reportKeywords.some(k => rawText.includes(k))) return [];

// แถวจาก v_employees: ชื่อเล่น · ตำแหน่งงาน · เวลาเข้างาน · วันหยุด · line_user_ids (ไอดีครบทุกบอท)
const employeeList = $input.all().map(i => i.json).filter(e => e['ชื่อเล่น']);
const employeeNames = employeeList.map(e => e['ชื่อเล่น']).join(', ');

const prompt = `คุณคือระบบจับคู่ชื่อพนักงานที่แจ้งลา/หยุด/สาย

รายชื่อพนักงานทั้งหมด: ${employeeNames}

ข้อความจากกลุ่ม LINE:
"${rawText}"

กฎสำคัญ:
1. @mention ในข้อความคือการแท็กหัวหน้า ไม่ใช่คนที่ลา → ละเว้น @mention ทั้งหมด
2. หาชื่อพนักงานที่ลา/หยุด/สายจากข้อความที่เหลือ (พิมพ์ผิด/ชื่อสั้น/bullet list ก็จับให้ได้)
3. ถ้าไม่พบชื่อพนักงานในข้อความ (นอกจาก @mention) → is_sender_self = true
4. ถ้าชื่อไม่มีในรายชื่อพนักงาน ให้ข้ามไป ห้ามเดา

ตอบเป็น JSON เท่านั้น ห้ามมีข้อความอื่น ห้ามมี markdown:
{
  "is_sender_self": false,
  "matched": [ { "nickname": "ชื่อเล่นจากรายชื่อตรงๆ", "confidence": "high|medium|low", "reason": "สั้นๆ" } ]
}`;

return [{ json: { prompt, rawText, senderUserId, employeeList } }];

// แปลงคำตอบ Gemini → แถวที่จะบันทึกหมายเหตุ (userId + note)
const aiText = $input.first().json?.candidates?.[0]?.content?.parts?.[0]?.text || '';
const prep = $('Prepare Prompt').first().json;
const employeeList = prep.employeeList || [];
const senderUserId = prep.senderUserId;
const rawText = prep.rawText;

let aiResult = null;
try { aiResult = JSON.parse(aiText.replace(/```json|```/g, '').trim()); }
catch (e) { console.log('parse ไม่ได้:', aiText); return []; }

const out = [];
const pushRow = (emp) => {
  // ★ คนเดียวมี LINE id ได้หลายตัว (บอทละ provider) — ส่งตัวที่ "ตรงกับคนส่ง" ถ้ามี ไม่งั้นเอาตัวแรก
  const ids = emp.line_user_ids || [];
  const uid = ids.includes(senderUserId) ? senderUserId : (ids[0] || '');
  if (!uid) { console.log('ยังไม่ผูก LINE:', emp['ชื่อเล่น']); return; }
  out.push({ json: { userId: uid, note: rawText, nickname: emp['ชื่อเล่น'], position: emp['ตำแหน่งงาน'] || '' } });
};

if (aiResult.is_sender_self) {
  const me = employeeList.find(e => (e.line_user_ids || []).includes(senderUserId));
  if (me) pushRow(me);
  return out;
}
for (const m of (aiResult.matched || [])) {
  const emp = employeeList.find(e => e['ชื่อเล่น'] === m.nickname);
  if (!emp) { console.log('ไม่มีในทะเบียน:', m.nickname); continue; }
  pushRow(emp);
}
return out;
